window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b510fee94f2c2182"]={"versions": [{"id": "FIG-b510fee94f2c2182", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm (Zeitverlaufsdiagramm) zur Spezifikation des Übertragungsverhaltens im Kommunikationsmodul der AUTOSAR Classic Platform (AUTOSAR COM). Das Diagramm stellt den Übertragungsmodus <code>MIXED</code> mit $n=3$ Wiederholungen bei Transmissionsmodus-Umschaltung (TMS-Switch) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitachse:</strong> Horizontale Zeitachse für Sendezeitpunkte und Ereignisse.</li>\n<li><strong>Signal-/I-PDU-Werte:</strong> Diskrete Werte $v = a$ und $v = b$.</li>\n<li><strong>Sende-Ereignisse (Trigger):</strong> Durch Blitz-Symbole dargestellte Wertänderungen.</li>\n<li><strong>Übertragungszeitpunkte (Tx):</strong> Durch grüne Pfeile auf der Zeitachse markierte Sendeinstanzen (sowie ein blau gestrichelter Pfeil zur Veranschaulichung der ursprünglichen Periodizität).</li>\n<li><strong>Zeitparameter:</strong></li>\n<li>$t_{c1}$: Zykluszeit der periodischen Übertragung im Modus 1 ($v=a$).</li>\n<li>$y \\cdot t_{c1}$: Vielfaches der Zykluszeit $t_{c1}$ nach Unterbrechung der Zeitachse.</li>\n<li>$t_{c2}$: Zykluszeit der periodischen Übertragung im Modus 2 ($v=b$).</li>\n<li>$z \\cdot t_{c2}$: Vielfaches der Zykluszeit $t_{c2}$ nach Unterbrechung der Zeitachse.</li>\n<li>$t_d$: Minimaler Abstand zwischen Übertragungen innerhalb eines Bursts (<code>ComTxIPduNumberOfRepetitions</code> mit $n=3$).</li>\n<li>$dt$: Minimaler Abstand bzw. Sperrzeit nach einer Übertragung.</li>\n<li>$t_{r,\\min}$: Minimale Reaktionszeit nach einem Trigger-Ereignis bis zur tatsächlichen Übertragung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer periodischer Modus ($v = a$):</strong> Periodische Aussendung von I-PDUs im Abstand von $t_{c1}$ bzw. $y \\cdot t_{c1}$.</li>\n<li><strong>TMS-Umschaltung auf Modus 2 ($v = b$):</strong> Eine Signalwertänderung ($v = b$) löst nach Ablauf von $dt$ und der minimalen Reaktionszeit $t_{r,\\min}$ die erste Übertragung aus. Daraufhin schaltet der Modus auf eine periodische Übertragung mit der neuen Zykluszeit $t_{c2}$ (bzw. $z \\cdot t_{c2}$) um.</li>\n<li><strong>TMS-Rückschaltung auf Modus 1 ($v = a$) mit Burst ($n=3$):</strong> Eine erneute Signalwertänderung ($v = a$) triggert nach $dt$ und $t_{r,\\min}$ eine Burst-Übertragung von insgesamt $n=3$ I-PDUs im Abstand von $t_d$. Nach dem letzten Burst-Frame wird die periodische Aussendung im Takt $t_{c1}$ fortgesetzt.</li>\n<li><strong>Erneutes Sende-Ereignis ($v = a$):</strong> Eine weitere Wertänderung führt erneut zu einem Burst ($n=3$ im Abstand $t_d$). Das Diagramm visualisiert anhand eines blau gestrichelten Pfeils und einer $t_{c1}$-Klammer die Resynchronisation der zyklischen Aussendung nach dem Ereignis.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Referenz für die Implementierung der I-PDU-Sende-Modi in AUTOSAR COM:</p>\n<ul class=\"fig-list\">\n<li>Im Modus <code>MIXED</code> werden zyklische Übertragungen mit ereignisgesteuerten Bursts (<code>ComTxIPduNumberOfRepetitions</code>) kombiniert.</li>\n<li>Umschaltung der Transmission Mode Selection (TMS) führt zur Anpassung der Periodendauer ($t_{c1} \\leftrightarrow t_{c2}$) und Konfiguration.</li>\n<li>Einhaltung der Mindestabstände ($t_d$, Mindestverzögerung $dt$, $t_{r,\\min}$) zur Buslastbegrenzung.</li>\n<li>Nach Abschluss einer ereignisgesteuerten Wiederholungssequenz wird der periodische Sendezyklus bezogen auf den letzten Burst-Frame neu getaktet.</li>\n</ul>"}, {"id": "FIG-4d73fdbd101d9504", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm (Zeitverlaufsdiagramm) zur Spezifikation des Übertragungsverhaltens im Kommunikationsmodul der AUTOSAR Classic Platform (AUTOSAR COM). Das Diagramm stellt den Übertragungsmodus <code>MIXED</code> mit $n=3$ Wiederholungen bei Transmissionsmodus-Umschaltung (TMS-Switch) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitachse:</strong> Horizontale, am rechten Ende mit $t$ beschriftete Zeitachse für Sendezeitpunkte und Ereignisse.</li>\n<li><strong>Signal-/I-PDU-Werte:</strong> Diskrete Werte $v = a$ und $v = b$.</li>\n<li><strong>Sende-Ereignisse (Trigger):</strong> Durch nach unten gerichtete rote Dreiecke markierte Wertänderungen.</li>\n<li><strong>Übertragungszeitpunkte (Tx):</strong> Durch grüne Pfeile auf der Zeitachse markierte Sendeinstanzen.</li>\n<li><strong>Zeitparameter:</strong></li>\n<li>$t_{c1}$: Zykluszeit der periodischen Übertragung im Modus 1 ($v=a$).</li>\n<li>$y \\cdot t_{c1}$: Vielfaches der Zykluszeit $t_{c1}$ (gestrichelte Bemaßung nach Achsenunterbrechung).</li>\n<li>$t_{c2}$: Zykluszeit der periodischen Übertragung im Modus 2 ($v=b$).</li>\n<li>$z \\cdot t_{c2}$: Vielfaches der Zykluszeit $t_{c2}$ (gestrichelte Bemaßung nach Achsenunterbrechung).</li>\n<li>$t_d$: Minimaler Abstand zwischen Übertragungen innerhalb eines Bursts ($n=3$).</li>\n<li>$d$: Minimaler Abstand bzw. Mindestverzögerung nach einer Übertragung (über geschweifte Klammern bemaßt).</li>\n<li>$t_{r,\\min}$: Minimale Reaktionszeit nach einem Trigger-Ereignis bis zur Übertragung (über geschweifte Klammern bemaßt).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer periodischer Modus ($v = a$):</strong> Periodische Aussendung von I-PDUs im Abstand von $t_{c1}$ bzw. $y \\cdot t_{c1}$.</li>\n<li><strong>TMS-Umschaltung auf Modus 2 ($v = b$):</strong> Eine Signalwertänderung auf $v = b$ triggert nach Ablauf der Mindestverzögerung $d$ und der Reaktionszeit $t_{r,\\min}$ die erste Übertragung. Anschließend läuft die zyklische Übertragung mit Zykluszeit $t_{c2}$ bzw. $z \\cdot t_{c2}$.</li>\n<li><strong>TMS-Rückschaltung auf Modus 1 ($v = a$) mit Burst ($n=3$):</strong> Die Signalwertänderung zurück auf $v = a$ führt nach $d$ und $t_{r,\\min}$ zu einem Burst aus $n=3$ Übertragungen im Abstand $t_d$.</li>\n<li><strong>Fortsetzung der zyklischen Aussendung ($v = a$):</strong> Im Anschluss an den dritten Burst-Frame wird die reguläre periodische Aussendung im Zyklus $t_{c1}$ fortgesetzt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Referenz für die Implementierung der I-PDU-Sende-Modi in AUTOSAR COM:</p>\n<ul class=\"fig-list\">\n<li>Im Modus <code>MIXED</code> werden zyklische Übertragungen mit ereignisgesteuerten Bursts (<code>ComTxIPduNumberOfRepetitions</code>) kombiniert.</li>\n<li>Umschaltung der Transmission Mode Selection (TMS) führt zur Anpassung der Periodendauer ($t_{c1} \\leftrightarrow t_{c2}$) und Konfiguration.</li>\n<li>Einhaltung der Mindestabstände ($t_d$, Mindestverzögerung $dt$, $t_{r,\\min}$) zur Buslastbegrenzung.</li>\n<li>Nach Abschluss einer ereignisgesteuerten Wiederholungssequenz wird der periodische Sendezyklus bezogen auf den letzten Burst-Frame neu getaktet.</li>\n</ul>"}], "trans": [{"from": "FIG-b510fee94f2c2182", "to": "FIG-4d73fdbd101d9504", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Vierter Übertragungszyklus (Rechts):</strong> Das dritte Sende-Ereignis (zweite Wertänderung $v=a$ mit $n=3$ Burst-Übertragungen im Abstand $t_d$ und anschließender Resynchronisation $t_{c1}$) wurde vollständig entfernt. Anstelle des zweiten Bursts läuft die periodische Sendung im Zyklus $t_{c1}$ weiter.</li>\n<li><strong>Ereignis-Symbolik:</strong> Die Blitz-Symbole für Signalwertänderungen wurden durch nach unten weisende rote Dreiecke ersetzt.</li>\n<li><strong>Pfeillinien für variable Perioden:</strong> Die Maßpfeile für $y \\cdot t_{c1}$ und $z \\cdot t_{c2}$ sind nun gestrichelt dargestellt.</li>\n<li><strong>Zeitachse:</strong> Die Zeitachse ist am rechten Ende mit $t$ beschriftet.</li>\n<li><strong>Intervall-Beschriftung:</strong> Die Minimalverzögerung $dt$ wird als $d$ notiert; die Maßpfeile für $d$ und $t_{r,\\min}$ wurden durch geschweifte Klammern unterhalb der gepunkteten Hilfslinien ersetzt.</li>\n</ul>"}]};
